ALTER TABLE public.mission_claims ADD COLUMN presented_at timestamptz; CREATE OR REPLACE FUNCTION trip_private.present_checkin(p_trip uuid,p_week integer,p_claim uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n public.game_nights; BEGIN SELECT * INTO n FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week; IF n.trip_id IS NULL OR n.skipped OR (n.host_id<>auth.uid() AND NOT trip_private.is_leader(p_trip)) THEN RAISE EXCEPTION 'Only tonight''s host or a leader can mark a presentation'; END IF; IF now() < n.starts_at - interval '12 hours' OR now() > n.starts_at + interval '3 hours 30 minutes' THEN RAISE EXCEPTION 'Present during game night'; END IF; UPDATE public.mission_claims SET presented_at=now(),updated_at=now() WHERE id=p_claim AND trip_id=p_trip AND phase='checkin' AND status='pending' AND presented_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Pending Check-In task not found'; END IF; END $$; CREATE OR REPLACE FUNCTION public.present_checkin(p_trip uuid,p_week integer,p_claim uuid) RETURNS void LANGUAGE sql SET search_path=public AS $$ SELECT trip_private.present_checkin(p_trip,p_week,p_claim) $$; GRANT EXECUTE ON FUNCTION public.present_checkin(uuid,integer,uuid) TO authenticated;